const input = $json || {};
const headers = input.headers || {};
const RESOLVED_SQL = "WITH target AS MATERIALIZED (\n  SELECT conversation.id, conversation.customer_id, conversation.status AS previous_status\n    FROM renovation_dev.conversations conversation\n   WHERE conversation.chatwoot_conversation_id = $1::text\n   LIMIT 1\n   FOR UPDATE\n), control AS MATERIALIZED (\n  SELECT control.*\n    FROM (SELECT 1) seed LEFT JOIN target ON true\n    CROSS JOIN LATERAL renovation_dev.resolve_chatwoot_bot_control($1::text, $2::timestamptz, $3::text) control\n), operation_settle AS MATERIALIZED (\n  SELECT renovation_dev.settle_chatwoot_handoff_operations($1::text, $2::timestamptz) AS settled\n    FROM control\n   WHERE control.control_updated\n), updated AS (\n  UPDATE renovation_dev.conversations conversation\n     SET status = 'closed'::renovation_dev.conversation_status,\n         closed_at = COALESCE(conversation.closed_at, $2::timestamptz),\n         updated_at = now()\n    FROM target\n   WHERE conversation.id = target.id\n     AND (\n       conversation.status = 'handed_off'::renovation_dev.conversation_status\n       OR (\n         conversation.status = 'bot_active'::renovation_dev.conversation_status\n         AND COALESCE((SELECT settled FROM operation_settle), 0) > 0\n       )\n     )\n     AND COALESCE((SELECT control_updated FROM control), false)\n     AND (conversation.handed_off_at IS NULL OR conversation.handed_off_at <= $2::timestamptz)\n  RETURNING conversation.id, conversation.status\n), logged AS (\n  INSERT INTO renovation_dev.interaction_logs (\n    customer_id, conversation_id, event_type, correlation_id, payload, success\n  )\n  SELECT\n    target.customer_id,\n    target.id,\n    'chatwoot_conversation_resolved',\n    $3::text,\n    jsonb_build_object(\n      'chatwoot_conversation_id', $1::text,\n       'control_reactivated', COALESCE((SELECT control_updated FROM control), false),\n       'handoff_operations_settled', COALESCE((SELECT settled FROM operation_settle), 0),\n      'formal_handoff_closed', EXISTS (SELECT 1 FROM updated),\n      'event', $4::text,\n      'status', $5::text,\n      'inbox_id', $6::text\n    ),\n    true\n  FROM (SELECT 1) seed\n  LEFT JOIN target ON true\n  WHERE COALESCE((SELECT control_updated FROM control), false)\n     OR EXISTS (SELECT 1 FROM updated)\n  RETURNING id\n)\nSELECT\n  $1::text AS chatwoot_conversation_id,\n  (SELECT id FROM target) AS conversation_id,\n  (SELECT previous_status::text FROM target) AS previous_status,\n  COALESCE((SELECT status::text FROM updated), (SELECT previous_status::text FROM target)) AS conversation_status,\n  COALESCE((SELECT control_updated FROM control), false) AS control_reactivated,\n  COALESCE((SELECT settled FROM operation_settle), 0) AS handoff_operations_settled,\n  EXISTS (SELECT 1 FROM updated) AS updated_to_closed,\n  EXISTS (SELECT 1 FROM target) AS local_conversation_found,\n  (SELECT id FROM logged) AS log_id;";
function env(name, fallback = '') { try { return $env[name] || fallback; } catch (error) { return fallback; } }
function readHeader(name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return '';
}
function normalizeTimestamp(value) {
  if (value === null || value === undefined || value === '') return null;
  const raw = String(value).trim();
  const numeric = Number(raw);
  const date = Number.isFinite(numeric)
    ? new Date(numeric < 9999999999 ? numeric * 1000 : numeric)
    : new Date(raw);
  return Number.isFinite(date.getTime()) ? date.toISOString() : null;
}
function normalizeKey(value) {
  return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
function changedStatus(source) {
  const list = source.changed_attributes || source.conversation?.changed_attributes || source.changes || [];
  if (!Array.isArray(list)) return '';
  for (const entry of list) {
    const name = entry.attribute_name || entry.name || entry.attribute || '';
    if (String(name).toLowerCase() === 'status') {
      return String(entry.current_value || entry.value || entry.to || '').toLowerCase();
    }
  }
  return '';
}
function normalizeResolvedEvent(input, config = {}) {
  const body = input.body && typeof input.body === 'object' ? input.body : input;
  const conversation = body.conversation || body;
  const inbox = body.inbox || conversation.inbox || {};
  const account = body.account || {};
  const event = String(body.event || body.name || body.event_type || '').trim();
  const changedToStatus = changedStatus(body);
  const status = String(changedToStatus || body.status || conversation.status || body.conversation_status || '').toLowerCase();
  const conversationId = String(conversation.id || body.conversation_id || body.id || '').trim();
  const inboxId = String(inbox.id || conversation.inbox_id || body.inbox_id || '').trim();
  const inboxName = String(inbox.name || conversation.inbox_name || '').trim();
  // Chatwoot NO manda cuenta a nivel raiz en conversation_status_changed: el
  // unico lugar donde aparece es dentro del ultimo mensaje. Verificado con el
  // payload real el 2026-08-15, que traia inbox_id pero ningun account.
  const lastMessage = Array.isArray(body.messages) && body.messages.length
    ? body.messages[body.messages.length - 1] || {}
    : {};
  const accountId = String(
    account.id || body.account_id || conversation.account_id || lastMessage.account_id || '',
  ).trim();
  const expectedInboxId = String(config.inboxId || '').trim();
  const expectedInboxName = String(config.inboxName || 'Agente AIGENTS RENOVACIONES 9663');
  const expectedAccountId = String(config.accountId || '').trim();
  const inboxMatches = (expectedInboxId && inboxId === expectedInboxId)
    || (expectedInboxName && normalizeKey(inboxName) === normalizeKey(expectedInboxName));
  // Ausente no es lo mismo que distinto. Lo que autentica este webhook es el
  // token dedicado de la query, y el inbox ya discrimina cual es nuestro; exigir
  // ademas una cuenta que Chatwoot a veces no manda descartaba TODOS los
  // resolve reales y dejaba cada handoff colgado para siempre. Una cuenta
  // presente y distinta se sigue rechazando.
  const accountMatches = !expectedAccountId || !accountId || accountId === expectedAccountId;
  const resolvedEvent = (event === 'conversation_status_changed' && status === 'resolved')
    || (event === 'conversation_resolved' && status === 'resolved')
    || (event === 'conversation_updated' && changedToStatus === 'resolved');
  if (!resolvedEvent || status !== 'resolved' || !/^\d+$/.test(conversationId) || !inboxMatches || !accountMatches) {
    return { route: 'ignore', reason: !inboxMatches ? 'other_inbox' : (!accountMatches ? 'other_account' : 'not_resolved') };
  }

  const explicitTimestamp = normalizeTimestamp(body.updated_at || conversation.updated_at || body.created_at || conversation.created_at);
  if (!explicitTimestamp) return { route: 'ignore', reason: 'missing_timestamp' };
  const eventAt = explicitTimestamp;
  const sourceEventKey = `cw-resolved:${conversationId}:${explicitTimestamp}`;
  return {
    route: 'resolved',
    chatwoot_conversation_id: conversationId,
    event,
    status,
    event_at: eventAt,
    source_event_key: sourceEventKey,
    inbox_id: inboxId,
    persist_sql: RESOLVED_SQL,
    persist_params: [conversationId, eventAt, sourceEventKey, event, status, inboxId],
  };
}
const expectedToken = env('RENOV_CHATWOOT_WEBHOOK_TOKEN');
function safeEqual(left, right) {
  const a = String(left || '');
  const b = String(right || '');
  if (!a || a.length !== b.length) return false;
  let diff = 0;
  for (let index = 0; index < a.length; index += 1) diff |= a.charCodeAt(index) ^ b.charCodeAt(index);
  return diff === 0;
}
const provided = readHeader('x-chatwoot-token') || readHeader('x-internal-token') || input.query?.token || '';
if (!expectedToken || !safeEqual(provided, expectedToken)) return [{ json: { route: 'ignore', reason: 'unauthorized' } }];
const config = {
  inboxId: env('RENOV_CHATWOOT_INBOX_ID'),
  inboxName: env('RENOV_CHATWOOT_INBOX_NAME', 'Agente AIGENTS RENOVACIONES 9663'),
  accountId: env('RENOV_CHATWOOT_ACCOUNT_ID'),
};
return [{ json: normalizeResolvedEvent(input, config) }];
